import itertools
import sys
import sympy as sp

def c_n_k(n, k):
    # number of vertices
    N = 1 << n
    parent = list(range(N))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx != ry:
            parent[ry] = rx

    # precompute masks with exactly k bits set
    masks = [sum(1 << i for i in comb) for comb in itertools.combinations(range(n), k)]

    for v in range(N):
        for m in masks:
            u = v ^ m
            if u > v:  # avoid processing each edge twice
                union(v, u)

    # count components
    roots = set(find(v) for v in range(N))
    return len(roots)

def main():
    total = 0
    for n in range(1, 11):
        for k in range(1, n+1):
            total += c_n_k(n, k)
